const data=window.PORTFOLIO;
const chatApiBase=location.hostname.toLowerCase()==='garasicarius.github.io'?'https://carl-joseph-aguas-portfolio.carlaguas12345.chatgpt.site':'';
const element=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e;};
function tags(items){const div=element('div','tags');items.forEach(i=>div.append(element('span','tag',i)));return div;}
function media(item,cls,index){const box=element(item.image?'button':'div',cls+(item.image?' image-button':''));if(item.image){const img=element('img');img.src=item.image;img.alt=item.title;img.loading='lazy';box.append(img);box.setAttribute('aria-label','View '+item.title);box.onclick=()=>{document.querySelector('#full-image').src=item.image;document.querySelector('#full-image').alt=item.title;document.querySelector('#image-caption').textContent=item.title;document.querySelector('#image-dialog').showModal();};img.onerror=()=>{box.replaceChildren(element('span','placeholder-title','Image unavailable'));box.disabled=true;};}else{box.append(element('span','placeholder-icon',cls==='project-media'?'</>':'▧'),element('span','placeholder-title',cls==='project-media'?'Project image coming soon':'Certificate image placeholder'));}if(cls==='project-media')box.append(element('span','media-no','0'+(index+1)));return box;}
data.skills.forEach(s=>{const card=element('div','skill');card.append(element('h3','',s.title),tags(s.items));document.querySelector('#skills').append(card);});
function projectGallery(project,index){
  if(!project.images?.length)return media(project,'project-media',index);
  const gallery=element('div','project-gallery'),preview=element('button','project-media image-button'),photo=element('img'),caption=element('p','gallery-caption'),thumbs=element('div','gallery-thumbs');
  preview.type='button';photo.loading='lazy';preview.append(photo);thumbs.setAttribute('role','group');thumbs.setAttribute('aria-label',project.title+' screenshots');caption.setAttribute('aria-live','polite');let active=0;
  const select=position=>{active=position;const item=project.images[position];photo.src=item.src;photo.alt=project.title+' — '+item.caption;preview.setAttribute('aria-label','Enlarge '+item.caption);caption.textContent=(position+1)+' / '+project.images.length+' · '+item.caption;Array.from(thumbs.children).forEach((b,i)=>b.setAttribute('aria-pressed',String(i===position)));};
  project.images.forEach((item,position)=>{const button=element('button','gallery-thumb'),image=element('img');button.type='button';button.setAttribute('aria-label','Show '+item.caption);image.src=item.src;image.alt='';image.loading='lazy';button.append(image);button.onclick=()=>select(position);thumbs.append(button);});
  preview.onclick=()=>{const item=project.images[active];document.querySelector('#full-image').src=item.src;document.querySelector('#full-image').alt=photo.alt;document.querySelector('#image-caption').textContent=project.title+' — '+item.caption;document.querySelector('#image-dialog').showModal();};
  gallery.append(preview,caption,thumbs);select(0);return gallery;
}
data.projects.forEach((p,i)=>{const card=element('article','project');const list=element('ul');p.contributions.forEach(c=>list.append(element('li','',c)));card.append(projectGallery(p,i),element('p','project-meta',p.category),element('h3','',p.title),tags(p.technologies),list);document.querySelector('#project-grid').append(card);});
data.certificates.forEach((c,i)=>{const card=element('article','certificate');const artwork=c.image?media(c,'certificate-media',i):element('div','certificate-progress');if(!c.image)artwork.append(element('span','course-mark',c.issuer==='Google'?'G':c.issuer==='Microsoft'?'⊞':'◇'),element('span','course-status',c.status));card.append(artwork,element('h3','',c.title));if(c.issuer)card.append(element('p','',c.issuer));if(c.date)card.append(element('p','',c.date));if(c.skills)card.append(element('p','certificate-skills',c.skills));document.querySelector('#certificate-grid').append(card);});
const icons={github:'<path d="M12 2a10 10 0 0 0-3.16 19.49c.5.09.68-.22.68-.48v-1.86c-2.78.6-3.37-1.18-3.37-1.18-.45-1.16-1.11-1.47-1.11-1.47-.91-.62.07-.61.07-.61 1 .07 1.53 1.03 1.53 1.03.89 1.53 2.34 1.09 2.91.83.09-.65.35-1.09.64-1.34-2.22-.25-4.55-1.11-4.55-4.94 0-1.09.39-1.98 1.03-2.68-.1-.25-.45-1.27.1-2.65 0 0 .84-.27 2.75 1.03A9.6 9.6 0 0 1 12 6.83a9.6 9.6 0 0 1 2.5.34c1.9-1.3 2.74-1.03 2.74-1.03.55 1.38.2 2.4.1 2.65.64.7 1.03 1.59 1.03 2.68 0 3.84-2.34 4.68-4.57 4.93.36.31.68.92.68 1.85v2.76c0 .27.18.58.69.48A10 10 0 0 0 12 2Z"/>',gmail:'<path d="M3 5h18v14H3Z" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="m3 6 9 7 9-7M3 19V7m18 12V7" fill="none" stroke="currentColor" stroke-width="2"/>',linkedin:'<rect x="2" y="2" width="20" height="20" rx="3" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M6 10h2v8H6zm0-4h2v2H6zm5 4h2v1c3-3 6-1 6 2v5h-2v-5c0-2-4-2-4 1v4h-2z"/>',facebook:'<path d="M14 22v-9h3l.5-4H14V7c0-1.2.4-2 2-2h2V1.5A23 23 0 0 0 15 1c-3 0-5 1.8-5 5v3H7v4h3v9Z"/>',instagram:'<rect x="3" y="3" width="18" height="18" rx="5" fill="none" stroke="currentColor" stroke-width="1.8"/><circle cx="12" cy="12" r="4" fill="none" stroke="currentColor" stroke-width="1.8"/><circle cx="17.5" cy="6.5" r="1.2"/>'};
for(const [key,label,url]of [['github','GitHub',data.personal.github],['gmail','Gmail','mailto:carljoseph.aguas@gmail.com'],['linkedin','LinkedIn',data.personal.linkedin],['facebook','Facebook',data.personal.facebook],['instagram','Instagram',data.personal.instagram]]){const item=element(url?'a':'span','social-link'+(url?'':' missing'));item.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor">'+icons[key]+'</svg>';if(key!=='facebook')item.append(element('span','',label));else item.setAttribute('aria-label','Facebook');if(url){item.href=url;if(!url.startsWith('mailto:')){item.target='_blank';item.rel='noopener noreferrer';}}else{if(key!=='facebook')item.append(element('small','','Link not added'));item.setAttribute('aria-disabled','true');}document.querySelector('#social-links').append(item);}
const messages=document.querySelector('#messages');let history=[],pending=null,conversation=0;
function message(text,user=false,source=''){const el=element('div','message'+(user?' user':''),text);if(source)el.append(element('small','',source));messages.append(el);messages.scrollTop=messages.scrollHeight;return el;}
function busy(value){document.querySelector('#chat-form button').disabled=value;document.querySelectorAll('[data-question]').forEach(b=>b.disabled=value);messages.setAttribute('aria-busy',String(value));}
function reset(){conversation++;pending?.abort();pending=null;history=[];busy(false);messages.replaceChildren();message('Ask me about my projects, skills, or interests.');}
async function ask(q){q=q.trim();if(!q||pending)return;const turn=conversation;message(q,true);const waiting=message('Thinking…');const controller=new AbortController();pending=controller;busy(true);const timer=setTimeout(()=>controller.abort(),30000);
  try{const response=await fetch(chatApiBase+'/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,history}),signal:controller.signal});const result=await response.json();if(turn!==conversation)return;waiting.remove();if(!response.ok){message(result.error||'Gemini could not respond. Please try again.');document.querySelector('#question').value=q;return;}if(typeof result.answer!=='string')throw new Error('Invalid answer');message(result.answer);history=[...history,{role:'user',text:q},{role:'assistant',text:result.answer}].slice(-12);
  }catch(error){if(turn!==conversation)return;waiting.remove();message(error.name==='AbortError'?'The request timed out. Please try again.':'The assistant could not connect. Please try again.');document.querySelector('#question').value=q;}
  finally{clearTimeout(timer);if(turn===conversation){pending=null;busy(false);if(!document.querySelector('#chat-panel').hidden)document.querySelector('#question').focus();}}
}
document.querySelector('#chat-form').onsubmit=e=>{e.preventDefault();const input=document.querySelector('#question');if(pending)return;const value=input.value;input.value='';ask(value);};
document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));document.querySelector('#clear-chat').onclick=reset;reset();
fetch(chatApiBase+'/api/chat/status').then(r=>{if(!r.ok)throw new Error();return r.json();}).then(s=>{if(!s.configured&&history.length===0&&!pending)message('Chat is awaiting setup. Please contact me by email for now.');}).catch(()=>message('Chat is unavailable. Please try again later.'));
const chatPanel=document.querySelector('#chat-panel'),chatLauncher=document.querySelector('#chat-launcher');let chatReturnFocus=chatLauncher;
function setChat(open,trigger=chatLauncher){chatPanel.hidden=!open;chatLauncher.setAttribute('aria-expanded',String(open));if(open){chatReturnFocus=trigger;messages.scrollTop=messages.scrollHeight;document.querySelector('#question').focus();}else{chatReturnFocus.focus();}}
chatLauncher.onclick=()=>setChat(chatPanel.hidden);
document.querySelector('#close-chat').onclick=()=>setChat(false);
document.querySelectorAll('.chat-open').forEach(button=>button.onclick=()=>setChat(true,button));
document.querySelector('#assistant').addEventListener('keydown',event=>{if(event.key==='Escape'&&!chatPanel.hidden){event.preventDefault();setChat(false);}});
document.querySelector('#close-image').onclick=()=>document.querySelector('#image-dialog').close();
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(pointer: fine)');let trailEnabled=!reduced.matches&&fine.matches,last=0;const trail=document.querySelector('#trail-layer'),toggle=document.querySelector('#trail-toggle');
function syncTrail(){toggle.textContent='Cursor trail: '+(trailEnabled?'on':'off');toggle.setAttribute('aria-pressed',String(trailEnabled));if(!trailEnabled)trail.replaceChildren();}syncTrail();toggle.onclick=()=>{trailEnabled=!trailEnabled;syncTrail();};reduced.addEventListener('change',()=>{trailEnabled=!reduced.matches&&fine.matches;syncTrail();});
const words=['const','{ }','build()','return','<div>','await','let','=>','0101','function','</>','new','[ ]','create()'];
document.addEventListener('pointermove',e=>{if(!trailEnabled||reduced.matches||e.pointerType!=='mouse'||e.timeStamp-last<85||e.target.closest('input,button,a,.chat'))return;last=e.timeStamp;const word=element('span','trail-word',words[Math.floor(Math.random()*words.length)]);word.style.left=(e.clientX+12)+'px';word.style.top=(e.clientY+10)+'px';trail.append(word);setTimeout(()=>word.remove(),1250);});
// The supplied artwork is clipped in CSS to exclude its white presentation panel.
const scenery=document.querySelector('#mountain-scene');let sceneryFrame=0;
function paintScenery(){sceneryFrame=0;const distance=reduced.matches?0:Math.min(scrollY*.075,120);scenery.style.transform=`translate3d(0,${-distance}px,0)`;}
addEventListener('scroll',()=>{if(!sceneryFrame)sceneryFrame=requestAnimationFrame(paintScenery);},{passive:true});reduced.addEventListener('change',paintScenery);paintScenery();
